package com.finsightai.service;
import com.finsightai.model.Transaction; import com.finsightai.repository.TransactionRepository; import org.apache.commons.csv.*; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.time.LocalDate;
@Service public class CsvImportService {private final TransactionRepository repo;private final AuditService audit;public CsvImportService(TransactionRepository r,AuditService a){repo=r;audit=a;}public int importFile(MultipartFile file)throws IOException{int count=0;try(Reader reader=new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8);CSVParser p=CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build().parse(reader)){for(CSVRecord r:p){Transaction t=new Transaction();t.setTransactionDate(LocalDate.parse(r.get("transactionDate")));t.setAccount(r.get("account"));t.setCategory(r.get("category"));t.setType(r.get("type"));t.setAmount(new BigDecimal(r.get("amount")));t.setDepartment(r.get("department"));t.setDescription(r.get("description"));t.setSourceSystem(r.get("sourceSystem"));repo.save(t);count++;}}audit.record("IMPORT","TRANSACTION",null,"Imported "+count+" CSV transactions");return count;}}
